import { getMetaContent } from "helpers/meta_helpers"

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

// Snap a timestamp to midnight using the timezone the server rendered with (the
// `timezone` meta tag), so client day boundaries match the server's instead of
// following the browser's resolved timezone, which can differ in a PWA.
function datePartsInTimezone(date) {
  return dateFormatter().formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

export function formatLocalTime(date, format = "time", now = new Date()) {
  switch (format) {
    case "time":
      return formatTime(date)
    case "date":
      return formatDate(date)
    case "date_with_year":
      return formatDateWithYear(date)
    case "weekday":
    case "weekday_date":
      return formatWeekdayDate(date)
    case "short_datetime":
      return formatShortDateTime(date)
    case "ago":
      return formatTimeAgo(date, now)
    case "day":
      return formatRelativeDay(date, now)
    default:
      return formatRelativeTime(date, now)
  }
}

export function fullLocalTime(date) {
  return intlFormat(date, {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit"
  })
}

export function formatTime(date) {
  return intlFormat(date, { hour: "numeric", minute: "2-digit" })
}

export function formatDate(date) {
  return intlFormat(date, { month: "short", day: "numeric" })
}

export function formatDateWithYear(date) {
  return intlFormat(date, { year: "numeric", month: "short", day: "numeric" })
}

export function formatWeekdayDate(date) {
  return intlFormat(date, { weekday: "long", month: "long", day: "numeric" })
}

export function formatShortDateTime(date) {
  return intlFormat(date, {
    year: "2-digit",
    month: "numeric",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit"
  })
}

// "Yesterday", "5 days ago", or "Sep 12" — the relative day for recent dates
// and an absolute date once they're more than a week away.
export function formatRelativeTime(date, now = new Date()) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    if (date < now) {
      return formatTime(date)
    } else {
      return relativeAmount(date - now)
    }
  } else if (days === -1) {
    return "yesterday"
  } else if (days === 1) {
    return "tomorrow"
  } else if (days < -1 && days > -7) {
    return `${-days} days ago`
  } else if (days > 1 && days < 7) {
    return `in ${days} days`
  } else {
    return formatDate(date)
  }
}

export function formatRelativeDay(date, now = new Date()) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return "today"
  } else if (days === -1) {
    return "yesterday"
  } else if (days === 1) {
    return "tomorrow"
  } else if (days < 0 && days > -7) {
    return `${-days} days ago`
  } else if (days > 0 && days < 7) {
    return `in ${days} days`
  } else {
    return formatDate(date)
  }
}

// "Less than a minute ago", "5 minutes ago", "3 days ago"... matching the
// granularity of Rails' time_ago_in_words.
export function formatTimeAgo(date, now = new Date()) {
  const seconds = (now - date) / 1000
  const magnitude = Math.abs(seconds)

  if (magnitude < 45) {
    return "just now"
  } else if (magnitude < 90) {
    return relativeAmount(-seconds, "minute", 1)
  } else if (magnitude < 45 * 60) {
    return relativeAmount(-seconds, "minute")
  } else if (magnitude < 90 * 60) {
    return relativeAmount(-seconds, "hour", 1)
  } else if (magnitude < 24 * 60 * 60) {
    return relativeAmount(-seconds, "hour")
  } else if (magnitude < 42 * 60 * 60) {
    return relativeAmount(-seconds, "day", 1)
  } else if (magnitude < 30 * 24 * 60 * 60) {
    return relativeAmount(-seconds, "day")
  } else if (magnitude < 60 * 24 * 60 * 60) {
    return relativeAmount(-seconds, "month", Math.round(magnitude / (30 * 24 * 60 * 60)))
  } else if (magnitude < 365 * 24 * 60 * 60) {
    return relativeAmount(-seconds, "month")
  } else {
    return relativeAmount(-seconds, "year")
  }
}

function relativeAmount(milliseconds, unit = null, value = null) {
  const units = {
    second: 1000,
    minute: 60 * 1000,
    hour: 60 * 60 * 1000,
    day: 24 * 60 * 60 * 1000,
    month: 30 * 24 * 60 * 60 * 1000,
    year: 365 * 24 * 60 * 60 * 1000
  }

  const chosenUnit = unit || smallestUnitFor(milliseconds)
  const chosenValue = value ?? Math.round(milliseconds / units[chosenUnit])

  return relativeTimeFormatter().format(chosenValue, chosenUnit)
}

function smallestUnitFor(milliseconds) {
  const magnitude = Math.abs(milliseconds)

  if (magnitude < 60 * 1000) return "second"
  if (magnitude < 60 * 60 * 1000) return "minute"
  if (magnitude < 24 * 60 * 60 * 1000) return "hour"
  if (magnitude < 30 * 24 * 60 * 60 * 1000) return "day"
  if (magnitude < 365 * 24 * 60 * 60 * 1000) return "month"
  return "year"
}

let relativeTimeFormatterCache

function relativeTimeFormatter() {
  return relativeTimeFormatterCache ??= new Intl.RelativeTimeFormat("en-US", { numeric: "always" })
}

function intlFormat(date, options) {
  return dateFormatterFor(options).format(date).replace(/\u202f/g, " ")
}

const intlFormatterCache = new Map()

function dateFormatterFor(options) {
  const key = JSON.stringify(options)

  if (!intlFormatterCache.has(key)) {
    intlFormatterCache.set(key, new Intl.DateTimeFormat("en-US", options))
  }

  return intlFormatterCache.get(key)
}

let dateFormatterCache
let dateFormatterTimezone

function dateFormatter() {
  const timezone = getMetaContent("timezone")

  if (!dateFormatterCache || dateFormatterTimezone !== timezone) {
    dateFormatterTimezone = timezone
    dateFormatterCache = buildDateFormatter(timezone)
  }

  return dateFormatterCache
}

function buildDateFormatter(timezone) {
  const options = { year: "numeric", month: "2-digit", day: "2-digit" }

  try {
    return new Intl.DateTimeFormat("en-US", { ...options, timeZone: timezone })
  } catch {
    return new Intl.DateTimeFormat("en-US", options)
  }
}
