import { BridgeComponent } from "@hotwired/hotwire-native-bridge"

export default class extends BridgeComponent {
  static component = "share"

  shareUrl() {
    const description = this.bridgeElement.bridgeAttribute("share-description") || this.#cardDescription()

    this.send("shareUrl", {
      title: document.title,
      url: window.location.href,
      description: description
    })
  }

  #cardDescription() {
    const added = this.#text(".card__meta-text--added")
    const author = this.#text(".card__meta-text--author").replace(/^By\s+/, "by ")
    const assignees = this.#text(".card__meta-text--assignees").toLowerCase()
    const updated = this.#text(".card__meta-text--updated")

    if (added && author && updated) {
      return [ added, `${author} and ${assignees}.`, updated ].filter(Boolean).join(" ").replace(/\s+/g, " ")
    }
  }

  #text(selector) {
    return this.element.ownerDocument.querySelector(selector)?.textContent.trim() || ""
  }
}
